   Rebirth: "重生",
   RebirthAndStartANewRun: "重生並開始新一輪",
   RebirthAndStartANewRunDesc:
      "光復者是一款<i>增量</i>大戰略遊戲——每一輪都會授予永久加成，使下一輪推進更快、走得更遠。這一系統稱為<i>重生</i>。<br>重生時，我們<i>吞併並核心化</i>的地塊將轉化為<icon>Legacy</icon>傳承點數——它們會帶入未來各輪並授予強大加成。<br>我們可為下一輪選擇不同行省——請按螢幕提示進行重生。<br>重生後，教程將告完成。憑藉新獲知的知識，我們已準備好制定自己的策略、開闢自己的道路——歷史的走向現由我們決定。",
