   TheCatastropheAtAdrianople: "阿德里安堡之災",
   TheCatastropheAtAdrianopleDesc: "軍團潰散，皇帝殞命。邊境燃燒，羅馬再度學會恐懼。",
   TheCostIsCalculatedAsFollows: "花費按以下方式計算",
   TheDeclineOfLugdunum: "盧格杜努姆的衰落",
   TheDeclineOfLugdunumDesc: "帝國改革的風暴吹過盧格杜努姆，寒意刺骨。這裡不再受寵為行省權力中心，官員與影響力逐漸流向遠方城市，昔日繁華街道日益沉寂。",
   TheEdictOfMilan: "米蘭敕令",
   TheEdictOfMilanDesc: "信徒不再於暗影中受獵，他們走向光明。羅馬敞開神廟——也敞開未來。",
   TheEdictOfThessalonica: "帖撒羅尼迦敕令",
   TheEdictOfThessalonicaDesc: "古羅馬諸神歸於沉寂，帝國以新的正統信仰統合——一信條、一教義、一神聖真理，將羅馬世界凝聚為一。",
   TheEffectIsCurrentlyActive: "該效果當前生效中！",
   TheEmperorsDivinityMustBeRespected: "必須尊崇皇帝的神性",
   TheEmperorWhoFellInBattle: "陣亡的皇帝",
   TheEmperorWhoFellInBattleDesc: "羅馬皇帝首度殞於外敵之手。軍團後撤，與他一同死去的，還有無敵的幻象。",
   TheEmperorWillBringStability: "皇帝將帶來穩定度",
   TheEmperorWillRestoreOurGlory: "皇帝將恢復我們的榮耀",
   TheEternalCityCannotBeReplaced: "永恆之城不可取代",
   TheFinalDivision: "最終分裂",
   TheFinalDivisionDesc: "皇帝狄奧多西入土為安，與他一同長眠的，還有羅馬脆弱的統一。再無一意主宰全境——東方與西方各行其道。",
   TheFixedCostOfDeclaringWar: "宣戰的固定費用。",
   TheFollowingConditionsMustBeMet: "須滿足以下條件",
   TheFollowingDiplomaticTreatiesAreAboutToExpire$1$2: "下列外交條約將於不到 $1 個月後到期：<i>$2</i>。",
   TheFollowingResourcesWillBeSpent: "將消耗以下資源",
   TheFollowingTileUpgradesWillBeReducedIfWeveWonTheWar: "若<i>我們贏得了戰爭</i>，下列地塊升級將被削減。",
   TheFollowingTrucesAreEnacted: "下列停戰協議已生效：",
   TheGodFromTheEast: "來自東方的神",
   TheGodFromTheEastDesc: "遙遠軍團以盾推舉一名少年祭司。他將新神帶入羅馬——羅馬為之震顫。",
   TheGreatPersecution: "大迫害",
   TheGreatPersecutionDesc: "古老諸神渴求虔敬。敕令刻於石上——信仰於烈火中經受考驗。",
   TheImperialMintInCrisis: "帝國鑄幣廠危機",
   TheImperialMintInCrisisDesc: "盧格杜努姆那曾經享譽高盧、以純度與信譽著稱的鑄幣廠，如今陷入醜聞。內亂與疏忽使欺詐與粗劣工藝盛行。",
   TheirAttitudeIsDeterminedAsFollows: "其態度按以下方式判定：",
   TheirAttitudeTowardsUsIsHigherThanTheDefenders: "其對我國態度高於防守方",
   TheirPrestige: "其威望",
   TheLastPaganEmperor: "最後的異教皇帝",
   TheLastPaganEmperorDesc: "神廟再度甦醒，香菸升向被遺忘的天穹。一位皇帝拒絕十字架，轉身迴歸奧林匹斯——但帝國敕令能否恢復往昔？",
   TheLegacyOfIrenaeus: "愛任紐的遺澤",
   TheLegacyOfIrenaeusDesc: "盧格杜努姆主教愛任紐已然謝世，留下神學明晰與牧養領導的傳世遺產。",
   TheLoireFloods: "盧瓦爾河氾濫",
   TheLoireFloodsDesc: "反常的雨季使盧瓦爾河暴漲，淹沒穀倉，沖毀碼頭。地方社群呼籲援助，商賈則主張投資更堅固的基礎設施。",
   TheNewRomeRises: "新羅馬崛起",
   TheNewRomeRisesDesc: "博斯普魯斯之濱，第二羅馬拔地而起——濱海扼守，天佑昌盛，註定永恆。",
   ThePraetoriansDecide: "禁衛軍做出抉擇",
   ThePraetoriansDecideDesc: "侍衛漸失耐心。皇帝被從宮中拖出，羅馬再度明白誰才真正握劍。",
   ThePriceOfWiseCounsel: "智者建言的代價",
   ThePriceOfWiseCounselDesc: "我們最信任的一眾顧問代表團已向總督請願加薪，以多年忠誠效力與日益沉重的生活開支為由。",
   ThePrideOfGaulRidesForth: "高盧之驕策馬出征",
   ThePrideOfGaulRidesForthDesc: "我們的將軍讚歎高盧騎兵的勇猛與兇悍，其雷霆衝鋒令一切對手膽寒。",
   TheQueenOfTheEast: "東方女王",
   TheQueenOfTheEastDesc: "沙漠中升起一位身披絲綢與野心的女王。東方屈膝的物件不是羅馬——而是帕爾米拉。",
   TheRiseOfDiocletian: "戴克裡先的崛起",
   TheRiseOfDiocletianDesc: "歷戰沙場的將士中走出一位鋼鐵意志的統治者。他不只修補帝國——他要重塑帝國。",
   TheRuleOfFour: "四帝共治",
   TheRuleOfFourDesc: "一人皇帝守不住世界。昔日一人失足之處，四人將並肩守望。",
   TheShepherdRisesOverLugdunensis: "牧者執掌盧格杜嫩西斯",
   TheShepherdRisesOverLugdunensisDesc: "城邦秩序動搖，貴族家族退縮，主教挺身成為權威支柱。他既施慈善又行正義，日益增長的屬靈影響力恐將掩蓋舊日治理之道。",
   TheShipHasSailedChristianityIsHereToStay: "木已成舟；基督教已成定局",
   TheSubmissionOfBritannia: "不列顛尼亞的臣服",
   TheSubmissionOfBritanniaDesc: "高盧帝國在西部的威勢無人敢挑戰，不列顛尼亞承認我們的霸權。他們降下旗幟，不是以被征服之敵，而是以忠誠附庸之身前來。",
   TheSunderingOfTheWest: "西部的分裂",
   TheSunderingOfTheWestDesc: "羅馬踉蹌之際，將領們擅自稱帝。行省不再坐等遠方主人。帝國四分五裂。",
   TheTideOfRefugeesAtTheRhine: "萊茵河畔的難民潮",
   TheTideOfRefugeesAtTheRhineDesc: "萊茵沿岸的動盪使難民如潮湧入盧格杜嫩西斯。其中有絕望的市民，也有流浪的部族，皆尋求躲避暴力與匱乏。",
   TheWarSpoilsBelongToUs: "戰利品歸我們所有",
   TheyAreAttackersAlly: "其為進攻方盟友",
   TheyAreAttackersClient: "其為進攻方附庸",
   TheyAreDefendersAlly: "其為防守方盟友",
