   TimedActionAppeaseDesc$1: "安撫叛軍可將<i>叛亂</i>降低$1。僅當地塊當前<i>未</i>處於叛亂狀態時可用。",
   TimedActionCrackdownDesc$1$2$3: "鎮壓叛軍可將<i>叛亂</i>重置為$1，但會使<i>動盪</i>在$3年內增加$2。僅當地塊當前處於叛亂狀態時可用。",
   TimedActionDemandElectionBackingDesc$1: "要求選舉支持可使其在即將到來的執政官選舉中承諾支持我們，從而使我們的行省支持度提高$1。",
   TimedActionDemandTileDesc: "作為列強要求割讓地塊，若對方接受我們的要求，則須將地塊割讓給我們。",
   TimedActionDemandTributeDesc: "作為列強要求進貢，若對方接受我們的要求，可獲得一次性金幣。",
   TimedActionDenounceDesc$1$2$3: "譴責某行省會使其對我們的態度降低$1，我們的威望提高$2（若為宿敵則為$3）。",
   TimedActionDeterAggressionDesc$1$2: "威懾侵略要求我們在該行省進攻其他行省時加入防守方。威懾生效期間，我們的威望提高$1（若為宿敵則為$2）。",
   TimedActionDissolveTreatyDesc: "撕毀條約可終止某行省與另一行省的外交條約，並阻止該行省締結新條約。",
   TimedActionEvangelizeTileDesc: "向信奉非基督宗教的地塊傳教，可使其改信本行省的宗教。",
   TimedActionFabricateCasusBelliDesc: "偽造宣戰理由可獲得對對方的<i>外交爭端</i>宣戰理由。",
   TimedActionForceAttackDesc$1$2: "發動強攻時，若我方進攻被擊退，將損失$1常備軍而非$2戰爭分數。",
   TimedActionFortifyBordersDesc$1: "加固邊境可使與戰爭目標地塊接壤的我方地塊人力提高$1。",
   TimedActionGuaranteeDefenseDesc$1: "保障防禦要求我們在其遭受攻擊時加入其防禦戰。保障生效期間，其對我國的態度提高$1。",
   TimedActionHireMercenariesDesc: "僱用僱傭兵可立即將軍隊補充至徵兵目標。",
   TimedActionInciteUnrestDesc$1: "煽動邊境動盪可使與我國行省接壤的對方地塊動盪提高$1。",
   TimedActionPlunderWarTileDesc: "掠奪戰爭地塊可降低<i>所需戰爭分數</i>，並削弱該地塊升級。",
   TimedActionPublicEnemyDesc$1: "將某行省宣佈為<i>公敵</i>會使其<i>威望</i>與<i>軍力</i>降低$1。所有其他行省均獲得針對其的<i>公敵</i>宣戰理由。",
   TimedActionRequestMilitaryAidDesc$1$2: "請求軍事援助可使我們的軍力提高$1，附庸的軍力降低$2。",
   TimedActionRevealElectionBackingDesc: "揭露選舉支持可讓我們知曉其已承諾支持的兩名候選人。",
   TimedActionSetGovernmentFocusDesc: "設定政府側重可提高側重方面的月度產出，代價是其餘兩方面產出降低。",
   TimedActionSubvertGarrisonDesc$1: "策反邊境駐軍可使與我國行省接壤的對方地塊防禦降低$1。",
   TimedActionSummonGovernorDesc$1$2: "召見附庸總督可使我們的威望提高$1，附庸的威望降低$2。",
   TimedActionUpgradeInfrastructureDesc: "升級地塊基礎設施需消耗行政點數，並提高該地塊的<i>土地稅</i>。",
   TimedActionUpgradePopulationDesc: "升級地塊人口需消耗軍事點數，並提高該地塊的<i>人力</i>。",
   TimedActionUpgradeProductionDesc: "升級地塊生產需消耗外交點數，並提高該地塊的<i>產出</i>。",
