   UnpauseTheGameDesc: "光復者採用經典的<q>可暫停即時制</q>大戰略玩法，載入時遊戲處於暫停狀態。準備就緒後，點選暫停按鈕（高亮顯示）或按<i>空格鍵</i>取消暫停。<br>預設遊戲速度為1秒（現即時間）= 1天（遊戲時間）。可在右上角面板調整速度。",
