   OurOwnDestinyDesc: "不再參與元老院選舉",
   WeHaveEnacted$1: "我們已實施$1",
   WeHaventEnacted$1: "我們尚未實施$1",
   WeHavePledgedSupportToLessThan2Candidates: "我們已向少於2名候選人承諾支持",
   SpawnProvinceEffectDesc$1$2: "一個新政權<i>$1</i>形成，擁有以下地塊：$2",
   TheSuebiSettleGallaecia: "蘇維匯定居加利西亞",
   TheSuebiSettleGallaeciaDesc: "蘇維匯人不再流浪。在加利西亞的綠色山丘上，他們放下刀劍，拿起耕犁——第一個建立在羅馬土地上的蠻族王國。",
   TheEternalCityFalls: "永恆之城陷落",
   TheEternalCityFallsDesc: "八百年來，從未有敵人攻破她的城牆。如今西哥特人在廣場上盛宴——世界得知，就連羅馬也會流血。",
   AKingdomWithinTheEmpire: "帝國境內的王國",
   AKingdomWithinTheEmpireDesc: "西哥特人經羅馬法令獲賜阿基坦尼亞。蠻族如今依據羅馬法律持有羅馬土地——今天的交易，明天的王國。",
   TheVandalsCrossToAfrica: "汪達爾人渡海前往非洲",
   TheVandalsCrossToAfricaDesc: "蓋塞裡克帶領族人渡過海峽，帝國的糧倉向他們敞開。非洲養育了羅馬數個世紀——如今或許將滋養她的敵人。",
   CarthageHasFallenAgain: "迦太基再度陷落",
   CarthageHasFallenAgainDesc: "迦太基不戰而陷，汪達爾人繼承了它的港口。羅馬的舊敵在新主人手中重生——而這一次，她擁有一支艦隊。",
   TheBurgundiansOfSapaudia: "薩保狄的勃艮第人",
   TheBurgundiansOfSapaudiaDesc: "在沃爾姆斯被擊潰，蒙羅馬慈悲饒恕，勃艮第人被安置在羅訥河沿岸，作為高盧的盾牌。但盾牌有時也會變成利劍。",
   TheCourtOfAttila: "阿提拉的宮廷",
   TheCourtOfAttilaDesc: "阿提拉如今獨自統治，多瑙河向他納貢。在潘諾尼亞的木製宮殿中，上帝之鞭注視著羅馬世界的兩半——並選擇打擊何處。",
   TheLongHairedKings: "長髮諸王",
   TheLongHairedKingsDesc: "來自北方沼澤的長髮國王們向南進逼，接連奪取城池。法蘭克人並不劫掠高盧——他們意欲佔有它，並統治它。",
   TheSaxonShoreBreaks: "撒克遜海岸崩潰",
   TheSaxonShoreBreaksDesc: "應召而來充當保護者，卻以繼承者之姿抵達。亨吉斯特的龍骨擱淺在肯特海岸——被羅馬遺棄的島嶼找到了新主人。",
   TheScourgeOfGodIsHalted: "上帝之鞭被遏止",
   TheScourgeOfGodIsHaltedDesc: "在卡塔洛尼平原上，羅馬與她的蠻族盟友並肩抗擊阿提拉。匈人終於被擊退——但勝利由羅馬和哥特的鮮血共同寫就。",
   TheAlemanniCrossTheRhine: "阿勒曼尼人跨越萊茵河",
   TheAlemanniCrossTheRhineDesc: "埃提烏斯已死，再無雙手能扼守上萊茵河。阿勒曼尼人湧入阿爾薩斯——舊日邊疆從此屬於阿拉曼尼亞。",
   FourteenDaysOfPlunder: "十四天劫掠",
   FourteenDaysOfPlunderDesc: "阿拉里克劫掠三日之處，蓋塞裡克取了十四天。汪達爾人將羅馬剝得只剩骸骨——並將一位皇后帶往迦太基。",
   TheKingOfTheOstrogoths: "東哥特人之王",
   TheKingOfTheOstrogothsDesc: "狄奧多里克從君士坦丁堡歸來，身負羅馬的狡黠與父輩的鐵血。東哥特人聚集在他的旗幟下——一個流浪的民族，眼中映著義大利。",
   AnEmpireEndsInSilence: "帝國在沉寂中終結",
   AnEmpireEndsInSilenceDesc: "一位少年皇帝被悄然送走，帝國權杖向東駛往君士坦丁堡。西方再未有人稱帝——也無人認為有此必要。",
   WeShallKeepAnEyeOnThem: "我們應當留意他們",
   WeShallAssistRomeToRebuild: "我們將協助羅馬重建",
   WeShallFortifyOurOwnDefense: "我們將加強自身防禦",
   RomeIsWhereverLegionsStand: "羅馬在軍團立足之處",
   FineLetThemSettleThere: "好吧，讓他們在那裡定居",
   AfricaMustBeDefendedAtAllCosts: "必須不惜一切代價保衛非洲",
   NegotiateAndContainThem: "談判並遏制他們",
   HmmOneMoreThreatToDealWith: "嗯…又一個需要應對的威脅",
   LetsHopeTheyStayPeaceful: "希望他們保持和平",
   WeShallPrepareForThisNewThreat: "我們將為這一新威脅做準備",
   LetUsSeeWhatComesOfThis: "讓我們拭目以待",
   TheSignsAreNotEncouraging: "徵兆不容樂觀",
   WeShallHonorOurBarbarianAllies: "我們將尊崇我們的蠻族盟友",
   TheVictoryBelongsToRomeAlone: "勝利只屬於羅馬",
   WeShouldNotUnderestimateThem: "我們不應低估他們",
   WeShallRansomTheCaptives: "我們將贖回俘虜",
   WeHaveNothingLeftToGive: "我們已一無所有",
   OurDestinyIsInOurOwnHands: "我們的命運掌握在自己手中",
   OneEmpireOneEmperorInTheEast: "一個帝國、一位皇帝——在東方",
