   BarbariansWillNotRaidIfAttitudeIsPositive: "如果蠻族對我們的態度為正，他們將不會襲擊我們的行省。",
   AttitudeTowardsUs: "對我們的態度",
   $1IsCurrentlyReceivingASignificantWarPowerBoostThatWillEndIn$2Months: "$1目前正獲得顯著的軍力提升，將在$2個月後結束。",
   PayingARansomWillEndTheRaidOnUsImmediately: "支付贖金將立即結束對我們的襲擊。",
