   UnitedFrontier: "聯合邊疆",
   CurrentlyRaidedBy$1: "當前遭受$1襲擊",
   $1CurrentlyGetsTheFollowingNegativeEffectsFromThisRaid: "$1當前正從此襲擊中獲得以下負面效果",
   BeyondTheRhineFrontier: "萊茵邊境之外",
   BeyondTheRhineFrontierDesc: "我們久經戰陣的部眾已逼近日耳曼尼亞的邊界。貝爾吉卡富饒的城市位於西方，盧格杜嫩西斯的道路通向高盧腹地，雷蒂亞則扼守上萊茵河。我們必須決定，下一步將把旗幟帶向何方。",
   TurnOurStandardsTowardBelgica: "將我們的旗幟轉向貝爾吉卡",
   MarchIntoTheHeartOfLugdunensis: "進軍盧格杜嫩西斯腹地",
   AdvanceAlongTheUpperRhineIntoRaetia: "沿上萊茵河挺進雷蒂亞",
   $1SeeksOurProtection: "$1尋求我們的庇護",
   RaetiaSeeksOurProtectionDesc: "沒有我們的援助，雷蒂亞已無法保衛其山間道路。其使節願獻上貢賦與臣服，以換取在日耳曼尼亞盾牌之下的長久庇護。",
   BelgicaSeeksOurProtectionDesc: "曾經驕傲的貝爾吉卡已淪為昔日強盛的殘影。其政務官如今遙望邊境之外，尋求一位能保全其城市與古老特權的保護者。",
   ThePassesToTheSouth: "通往南方的山口",
   ThePassesToTheSouthDesc: "日耳曼尼亞的勢力如今已抵達阿爾卑斯山口。山口之外是富饒的納博訥西斯與義大利，其邊境守軍分散，尚未準備好應對來自北方的進攻。",
   DescendUponNarbonensis: "向納博訥西斯進軍",
   $1TileDefenseFor$2And$3For$4Years: "$1地塊防禦，作用於$2和$3，持續$4年",
   CarryOurStandardsIntoItalia: "將我們的旗幟帶入義大利",
   GermaniaAscendant: "日耳曼尼亞崛起",
   GermaniaAscendantDesc: "曾經充滿爭議的邊境如今已成為橫跨萊茵河與阿爾卑斯山的強大國度。為了長存，新的日耳曼尼亞必須選擇其力量所依託的制度。",
   EntrustTheRealmToSeasonedMagistrates: "將國政託付給資深政務官",
