   FocusedGovernanceDesc$1: "當前政府側重點每月提供相應類別的 $1 政府點數",
   ExtensiveAdministration: "廣泛行政",
   TheSilverOfCarthagoNova: "新迦太基之銀",
   TheSilverOfCarthagoNovaDesc: "新迦太基附近的古老礦區仍蘊藏著銀鉛礦脈，但淹水的坑道與老舊的裝置限制了產量。帝國工程師認為，一筆鉅額投資可以讓礦山重新盈利。",
   DrainTheOldWorkings: "排幹舊礦井",
   LeaseTheMinesToContractors: "將礦山租給承包商",
   TheGamesOfTarraco: "塔拉科競技會",
   TheGamesOfTarracoDesc: "塔拉科的政務官提議舉辦一場配得上行省首府的競技會。這些盛大表演將使各城市更忠於我們的統治，並彰顯其繁榮——前提是有人願意為此買單。",
   FundMagnificentGames: "資助盛大的競技會",
   MakeTheCitiesPay: "讓各城市出錢",
   TheMartyrdomOfFructuosus: "弗魯克圖奧蘇斯殉道",
   TheMartyrdomOfFructuosusDesc: "塔拉科主教弗魯克圖奧蘇斯與其兩位執事奧古裡烏斯和歐洛吉烏斯一同被燒死在競技場中。這場處決本為維護帝國權威，然而受刑者的從容堅定卻鼓舞了行省的基督徒。",
