   WallsForBarcino: "巴爾基諾城牆",
   WallsForBarcinoDesc: "劫掠與內戰暴露了舊有城市防禦的薄弱。巴爾基諾請求獲准修築一道堅固的新城牆，但塔拉科擔心，這項投資會將商業與影響力吸引到北方。",
   RaiseBarcinosCircuitOfTowers: "為巴爾基諾修築環城塔樓",
   ConcentrateResourcesAtTarraco: "將資源集中於塔拉科",
   TheNewTaxSurvey: "新稅務普查",
   TheNewTaxSurveyDesc: "戴克裡先的財政改革要求將塔拉科嫩西斯的每座莊園、每片田地和每名納稅人登記在新的稅務冊上。嚴格的普查能確保穩定可期的收入，但早已飽受徵用之苦的城市懇求從寬處置。",
   SurveyEveryEstate: "清查每座莊園",
   GrantTheCitiesALighterAssessment: "減輕城市的稅額評定",
   TheIrrigatorsOfTheEbro: "埃布羅河灌溉者",
   TheIrrigatorsOfTheEbroDesc: "淤泥與失修的堤岸威脅著埃布羅河谷的運河。市政議會請求行省財政出資修復，而大地主則願意承攬工程，條件是取得水源控制權。",
   RepairThePublicCanals: "修復公共運河",
   GrantTheWatersToTheGreatEstates: "將水源交給大莊園",
   PrudentiusSingsOfChristianRome: "普魯登提烏斯詠頌基督教羅馬",
   PrudentiusSingsOfChristianRomeDesc: "詩人普魯登提烏斯結束帝國任職歸來，開始創作將古典學識與基督教虔敬融為一體的詩篇。他的作品既可為塔拉科嫩西斯贏得聲望，也可在宮廷中成為雄辯之聲。",
   PatronizeThePoet: "資助這位詩人",
   EmployHimAsAnImperialAdvocate: "任用他為帝國辯護者",
   MaximusTakesThePurpleInHispania: "馬克西穆斯在伊斯帕尼亞稱帝",
   MaximusTakesThePurpleInHispaniaDesc: "隨著比利牛斯山以北的帝國權威瓦解，將軍格隆提烏斯在伊斯帕尼亞擁立馬克西穆斯為爭位皇帝。其支持者許諾提供保護，而忠於正統者則警告，新的篡位只會招致入侵。",
   RecognizeTheHispanicEmperor: "承認伊斯帕尼亞皇帝",
   HoldTarracoForTheLawfulEmperor: "為合法皇帝守住塔拉科",
