   TheLastRomanProvinceInHispaniaDesc: "蠻族諸王已瓜分伊斯帕尼亞大部，但塔拉科嫩西斯仍由羅馬治理。難民與失勢官員擠滿道路，既帶來了有用的才幹，也帶來了飢餓與動亂。",
   ReceiveTheRefugeesAndOfficials: "接納難民與官員",
   SealTheMountainPasses: "封鎖山口",
   TheBagaudaeOfTheEbro: "埃布羅河谷的巴高達",
   TheBagaudaeOfTheEbroDesc: "農民、逃兵和地方豪強在埃布羅河谷結成了武裝團伙。有人稱他們為匪徒，也有人聲稱，他們是在保護那些遭官員和稅吏遺棄的社群。",
   CrushTheRebels: "鎮壓叛亂者",
   ReduceRentsAndLevies: "減免租稅與徵收",
   RecognizeTheLocalMilitias: "承認地方民兵",
   AFootholdInBaetica: "拜提卡的立足點",
   AFootholdInBaeticaDesc: "我們在拜提卡北部的勝利，使肥沃的莊園、繁榮的城鎮和久經沙場計程車兵歸於塔拉科嫩西斯統治。如今必須按照行省最迫切的需要整頓這些新領土。",
   EnterTheEstatesOnOurTaxRolls: "將莊園錄入我們的稅冊",
   RestoreTheFieldsAndWorkshops: "恢復田地與工坊",
   RecruitTheConqueredGarrisons: "徵募已降服的守軍",
   BaeticaLiesExposed: "拜提卡門戶洞開",
   BaeticaLiesExposedDesc: "拜提卡已退守寥寥幾座孤立要塞。其指揮官為如何保衛殘餘領土爭執不休，給了我們的探員在最終戰役前削弱該行省的機會。",
   UndermineTheFrontierForts: "破壞邊境要塞",
   $1Gets$2TileDefenseFor$3Years: "$1獲得$2地塊防禦，持續$3年",
