   AnAccordWithLusitania: "與盧西塔尼亞的協定",
   AnAccordWithLusitaniaDesc: "盧西塔尼亞使節抵達塔拉科，尋求正式結盟。合作將使兩個行省共同受益，但我們的議會必須決定由哪個政府部門主導這份新協定。",
   ExchangeProvincialMagistrates: "互派行省政務官",
   EstablishAJointEmbassy: "設立聯合使館",
