   TheDistressOfLusitania: "盧西塔尼亞之困",
   TheDistressOfLusitaniaDesc: "債務與收入下滑耗空了盧西塔尼亞的國庫。其政務官願出售卡佩拉及周邊土地，不過一筆較小的援助或許既能保全其領土，也能贏得其感激。",
   PurchaseCaperaForTarraconensis: "為塔拉科嫩西斯購下卡佩拉",
