   GrantOurAllyEmergencyRelief: "向盟友提供緊急援助",
   LetLusitaniaPayItsOwnDebts: "讓盧西塔尼亞自行償債",
   LusitaniaUnderOurProtection: "受我們保護的盧西塔尼亞",
   LusitaniaUnderOurProtectionDesc: "沒有我們的黃金與影響力，盧西塔尼亞已無法維持其地位。其領袖願接受塔拉科嫩西斯的保護，以換取其職位與邊疆的安全。",
   ReceiveLusitaniaAsOurClient: "接納盧西塔尼亞為我們的附庸",
   TheRoadsIntoGaulDesc: "塔拉科嫩西斯如今掌控了西班牙的道路與關隘。越過比利牛斯山，兩條道路通往高盧：一條沿海岸通往納博訥西斯，另一條穿過阿基坦尼亞西部的谷地。我們的議會必須決定下一場戰役從何處開始。",
   MarchAlongTheCoastIntoNarbonensis: "沿海岸進軍納博訥西斯",
   OpenTheWesternRoadIntoAquitania: "打通通往阿基坦尼亞的西部道路",
   AcrossTheStraitOfGibraltar: "橫渡直布羅陀海峽",
   AcrossTheStraitOfGibraltarDesc: "拜洛既已落入我們掌控，唯有一道狹窄海峽將我們的領地與茅利塔尼亞海岸隔開。那裡的港灣意味著對西地中海的支配，但遠征非洲需要我們訴諸武力，或是從長計議。",
   LaunchTheInvasionFromBaelo: "從拜洛發動入侵",
   PlanTheAfricanCampaignWithCare: "審慎籌劃非洲戰役",
   TheRoadsIntoGaul: "通往高盧之路",
   TreatyRevenues: "條約收益",
   $1LandTaxForEachDiplomaticTreaty: "每項外交條約提供 $1 土地稅",
   VictoriousLeadership: "凱旋統御",
   $1PrestigeFor$2YearsAfterWinningAWarAsLeadAttackerOrDefender: "作為主導進攻方或防守方贏得戰爭後，$2 年內獲得 $1 威望",
   PaxLusitana: "盧西塔尼亞和平",
   $1TileOutputWhileNotAtWar: "未處於戰爭時，地塊產出 $1",
   TheSuebiMustBeDrivenOut: "必須驅逐蘇維匯人",
   TheSuebiMustBeDrivenOutDesc: "蘇維匯人的入侵浪潮已經退去，但他們的戰士仍佔據著從西班牙割據而來的王國。現在正是推翻其統治、重新統一半島之時。",
   $1NoLongerHas$2: "$1 不再擁有<i>$2</i>",
   TurnTheirStrongholdsAgainstThem: "讓他們的據點反噬自身",
   ShatterTheirWillToFight: "瓦解他們的戰意",
   AFootholdInAfrica: "非洲立足點",
   AFootholdInAfricaDesc: "我們的軍隊已在非洲海岸建立橋頭堡，使茅利塔尼亞的堡壘與駐軍暴露在兵鋒之下。一場堅決的戰役足以將這處立足點化為新的領土。",
   TurnTheirFortressesAgainstThem: "讓他們的堡壘反噬自身",
