   OurReligionIsNotChristian: "我們的宗教不屬於基督宗教",
   OurReligionIsChristian: "我們的宗教屬於基督宗教",
   OurProvinceReligionIsChristian: "我們行省的宗教屬於基督宗教",
   TileReligionIsNotChristian: "地塊宗教不屬於基督宗教",
   ChristianInfluenceConversionEffectsDescription: "若基督宗教影響力高於治理花費且我們的宗教不屬於基督宗教，或低於治理花費且我們的宗教屬於基督宗教，則應用以下效果。",
   ChristianInfluence: "基督宗教影響力",
   ChristianInfluencePerYear: "每年基督宗教影響力",
   ChristianInfluencePerYearDesc: "這是我們行省每年獲得的基督宗教影響力。",
   $1ChristianInfluenceIsAtLeast$2: "$1的基督宗教影響力至少為$2",
   ChristianInfluenceIsHigherThanGoverningCost: "基督宗教影響力高於治理花費",
   $1SpreadsTo$2And$3OfTheChristianTiles: "$1傳播至$2，並影響基督宗教地塊的$3。",
   TheSchismAtCarthage: "迦太基教會分裂",
   TheSchismAtCarthageDesc: "凱基利安受祝聖為迦太基主教，導致阿非利加教會分裂。他的反對者拒絕承認那些被指控在迫害期間交出經卷的教士，並堅稱一個被背叛玷汙的教會無法施行真正的聖禮。",
   TheAfricanChurchIsDivided: "阿非利加教會已然分裂",
   AriusChallengesTheBishops: "阿里烏斯挑戰眾主教",
   AriusChallengesTheBishopsDesc: "司鐸阿里烏斯宣稱，聖子由聖父所造，並非自永恆即已存在。亞歷山大里亞的譴責未能使他噤聲；東方各行省的主教與會眾紛紛選邊站隊。",
   TheControversySpreads: "爭議不斷蔓延",
   TheSpiritIsCalledIntoQuestion: "聖靈遭到質疑",
   TheSpiritIsCalledIntoQuestionDesc: "君士坦丁堡的馬其頓尼烏斯之追隨者承認聖子的神性，卻否認聖靈與聖父、聖子同等。他們的教義正贏得色雷斯與亞細亞眾多主教和會眾的支援，使許多人以為已經平息的爭論再度燃起。",
   TheCreedIsContestedOnceMore: "信條再度受到挑戰",
   TheTeachingsOfPelagius: "伯拉糾的教義",
   TheTeachingsOfPelagiusDesc: "來自不列顛尼亞的苦修士伯拉糾教導說，每個人生來無罪，並能憑藉自由意志選擇行義。他的思想從義大利到阿非利加都贏得了仰慕者，而希波的奧古斯丁則警告說，這套學說幾乎不給神聖恩典留下位置。",
   TheDebateOverGraceBegins: "恩典之爭由此開始",
   NestoriusRejectsTheotokos: "聶斯脫裡拒絕“誕神女”稱號",
   NestoriusRejectsTheotokosDesc: "新任君士坦丁堡主教聶斯脫裡反對將瑪利亞稱作“誕神女”，即上帝之母。他的佈道點燃了關於基督神人二性如何結合的更大爭論，紛爭正蔓延至整個東方教會。",
   ThePulpitsRingWithControversy: "講壇上爭論之聲不絕",
   ChalcedonDividesTheEast: "迦克墩使東方教會分裂",
   ChalcedonDividesTheEastDesc: "迦克墩大公會議宣告基督是一個位格、具有兩種本性，但埃及和敘利亞的許多基督徒拒絕這一信條。他們堅持聖言道成肉身後只有一種合一的本性，並譴責這項決議背叛了亞歷山大里亞的西里爾。",
   TheCouncilHasNotBroughtPeace: "大公會議未能帶來和平",
   OneWillInChrist: "基督唯有一志",
   OneWillInChristDesc: "希拉剋略皇帝認可了一項新信條，宣稱基督具有兩種本性，卻只有一個意志。這一教義本想調和迦克墩派與基督合一性論者，卻引發了從羅馬到東方各牧首區的新一輪抵制。",
   TheCompromiseSatisfiesNoOne: "這一妥協無人滿意",
   TheWarAgainstTheIcons: "反對聖像之戰",
   TheWarAgainstTheIconsDesc: "帝國官員正從教堂和公共場所移走聖像，宣稱對聖像的敬禮是一種偶像崇拜。修士、主教和信徒挺身捍衛聖像，這場爭論正使帝國各地的社群陷入分裂。",
   SacredImagesBecomeABattleground: "聖像成為爭奪的戰場",
