   InstalledMods: "已安裝的模組",
   ModsManagerDescription: "模組分為兩類：<i>附加模組</i>和<i>全轉換模組</i>。可以同時載入多個附加模組，但只能載入一個全轉換模組。模組之間可能互不相容。遊戲會記住上次載入的模組。",
   Addon: "附加模組",
   TotalConversion: "全轉換模組",
   Loading$1: "正在載入 $1...",
   TutorialIncreaseGameSpeedDesc$1$2$3: "每月嘗試$1次攻擊，最終結果由這些攻擊結果中的多數決定。若成功，我們獲得$2戰爭分數；否則失去相同數量。<br>戰爭進行期間，請按照螢幕提示將遊戲速度提高至$3。",
   TutorialSignPeaceTreatyAfterVictoryDesc$1: "一旦我們達到所需的戰爭分數，右側的進行中戰爭圖示就會跳動。點選該圖示並按照螢幕提示簽署和平條約，以便我們佔領<Tile>$1</Tile>。我們還可以從可用選項中選擇一項附加和平條款。<br>不妨暫停遊戲或降低遊戲速度，以便從容操作。",
   AdoptASocialClassAgenda: "採納一項社會階層議程",
   TutorialSocialClassAgendaDesc: "我們的行省中存在不同的社會階層，每個階層都支持某些議程，並反對另一些議程。請按照螢幕提示採納一項議程：支持該議程的階層將提高影響力，反對該議程的階層則會降低忠誠度。<br>注意不要讓任何社會階層的影響力過高或忠誠度過低，否則會引發負面後果。",
   LetMissionsGuideOurRestoration: "讓任務指引我們的復興",
   TutorialMissionsDesc$1$1: "每個行省都有一組獨特的任務；完成每項任務後，我們可以從多個獎勵中選擇一項。請按照螢幕提示檢視<icon>Mission</icon><i>$1</i>任務；將滑鼠懸停在每個獎勵選項上即可檢視詳情。<br>在最初幾輪中，遵循任務指引有助於我們儘早積累優勢。<br>完成<i>$1</i>或點選下方按鈕後，教程將繼續。",
   IllCompleteTheMissionLater: "我稍後再完成任務",
