   ChangeGovernmentFocus: "更改政府側重點",
   TutorialChangeGovernmentFocusDesc: "進攻戰爭每月需要消耗<icon>Military</icon>軍事點數。宣戰前，我們應將政府側重點改為軍事；這樣可以提高每月軍事點數收入，但會犧牲另外兩種政府點數。",
   MadeCoreTileRemainsCoreAfterReconquest: "地塊一旦被核心化，即使失去也仍會保留我們的核心；重新徵服後無需再次將其核心化。",
