   ProductiveInvestmentDesc$1: "每次升級地塊時，該地塊的產出提高$1",
   CommercialRenown: "商業聲望",
   $1PrestigeForEachActiveTrade: "每項進行中的貿易使威望提高$1",
   TheMilestonesOfRaetia: "雷蒂亞的里程碑",
   TheMilestonesOfRaetiaDesc: "塞普蒂米烏斯·塞維魯在位期間，雷蒂亞各地的里程碑記錄著道路修繕的重啟。阿爾卑斯道路連線義大利與多瑙河，承載著官員、商人與軍團；我們必須決定如何籌措這項昂貴工程的資金。",
   RebuildTheViaRaetia: "重建維亞·雷蒂亞",
