   CaracallaCrossesRaetia: "卡拉卡拉穿越雷蒂亞",
   CaracallaCrossesRaetiaDesc: "卡拉卡拉從義大利北部抵達，穿過我們的行省迎戰阿勒曼尼人。他的官員要求提供糧秣、替換戰馬與嚮導，但皇帝駕臨也讓我們難得有機會向帝國宮廷請願。",
   ProvisionTheImperialArmy: "為帝國軍隊提供補給",
   PetitionForStrongerPassForts: "請求加固山口要塞",
   SellSuppliesAtWartimePrices: "按戰時價格出售補給",
   TheAlamanniBreakTheFrontier: "阿勒曼尼人突破邊疆",
   TheAlamanniBreakTheFrontierDesc: "一場大規模的阿勒曼尼入侵襲擊了上日耳曼—雷蒂亞邊疆。西部雷蒂亞的軍隊不足以保護每座要塞與定居點，我們的議會要求決定行省防線應在哪裡堅守。",
   HoldEveryFortOnTheOuterWall: "守住外牆上的每座要塞",
   ScreenTheTownsWithFieldTroops: "以野戰部隊掩護城鎮",
   AbandonTheExposedDistricts: "放棄暴露的轄區",
   TheBrennerPassLiesOpen: "布倫納山口門戶洞開",
   TheBrennerPassLiesOpenDesc: "一支阿勒曼尼軍隊穿過布倫納山口進入義大利北部，而羅馬軍隊正被各地危機牽制。我們必須決定，疲憊不堪的駐軍能否在克勞狄烏斯皇帝抵達前守住這條阿爾卑斯道路。",
   SealTheBrennerPass: "封鎖布倫納山口",
   HarassTheInvadersRetreat: "騷擾撤退中的入侵者",
   LetTheHostPassIntoItalia: "放任這支軍隊進入義大利",
   TheAugustiAtAugustaVindelicum: "兩位奧古斯都駕臨奧古斯塔·溫德利庫姆",
   TheAugustiAtAugustaVindelicumDesc: "又一次阿勒曼尼入侵後，戴克裡先從雷蒂亞發起反擊；帝國行程表顯示，他隨後在奧古斯塔·溫德利庫姆與馬克西米安會面。他們的到來讓我們負責接待兩個帝國宮廷。",
   StageAnImperialReception: "籌辦帝國接待",
   SupplyScoutsForTheCounterattack: "為偵察兵提供反攻補給",
   PetitionForFrontierFunds: "請求邊疆經費",
   RaetiaDivided: "雷蒂亞一分為二",
   RaetiaDividedDesc: "帝國敕令要求我們分割雷蒂亞的檔案、收入與官員。奧古斯塔·溫德利庫姆將治理雷蒂亞第二省，而庫里亞掌管雷蒂亞第一省；我們必須決定要多麼忠實地執行這次重組。",
   CarryOutTheDivisionFaithfully: "忠實執行分省令",
   KeepTheBestOfficesAtAugusta: "將最好的官職留在奧古斯塔",
   SendTroopsAndFundsToCuria: "向庫里亞派遣部隊與資金",
   ConstantiusAtTheCampiCannini: "君士坦提烏斯與坎皮·卡尼尼",
   ConstantiusAtTheCampiCanniniDesc: "倫提恩西人一再越過邊境，促使君士坦提烏斯二世前往坎皮·卡尼尼。阿爾貝蒂奧在進軍前請求我們提供行省部隊、嚮導與補給，而當地地主則懇求我們的保護。",
   AttachOurBestTroopsToArbetio: "將我們最精銳的部隊交給阿爾貝蒂奧",
   FortifyTheCampiCannini: "加固坎皮·卡尼尼",
   OfferTheLentiensesNewTerms: "向倫提恩西人提出新條件",
