   ValentiniansFrontierTowersDesc: "瓦倫提尼安下令加固邊境，命令傳到了我們的官署。國庫無法建造帝國工程師提議的每一座塔樓與糧倉，因此我們必須確定雷蒂亞在這項計劃中的優先事項。",
   RaiseAChainOfBurgi: "修建一連串邊境塔堡",
   BuildGranariesBesideTheTowers: "在塔樓旁修建糧倉",
   RepairOnlyTheStrongestForts: "只修繕最堅固的要塞",
   BautoCallsTheSteppeWarriors: "鮑託召來草原戰士",
   BautoCallsTheSteppeWarriorsDesc: "朱滕吉人劫掠雷蒂亞第二省的富饒土地。鮑託請求我們的行政機構支付費用併為他召來的匈人與阿蘭人提供駐地，以輔助部隊取代一種危險；而這些人的忠誠建立在金錢與掠奪之上。",
   PayBautosHunsAndAlans: "支付鮑託的匈人與阿蘭人",
