   StilichosWinterInRaetiaDesc: "平定汪達爾人與阿蘭人對雷蒂亞的入侵後，斯提利科下令軍隊南下迎擊阿拉里克進軍義大利的部隊。我們必須決定要多大程度上服從，同時確保自己暴露在外的行省安全。",
   ReleaseTheTroopsForItalia: "放行前往義大利的部隊",
   KeepTheAlpinePassesManned: "讓阿爾卑斯山口駐有守軍",
   PetitionToSettleThemAsFederates: "請求將他們安置為盟民",
   BurcoAtTheCampiCannini: "布林科與坎皮·坎尼尼",
   BurcoAtTheCampiCanniniDesc: "九百名阿勒曼尼人穿過我們的行省，向義大利進發；馬約裡安的軍官布林科在坎皮·坎尼尼將他們殲滅。如今他請求我們的行政機構確保山口安全，並決定倖存俘虜的命運。",
   HuntTheSurvivorsThroughTheAlps: "在阿爾卑斯山中追捕倖存者",
   StrengthenTheAlpineWatch: "加強阿爾卑斯守備",
   RecruitTheCapturedWarriors: "招募被俘的戰士",
   ARealmBeyondTheNorthernFrontier: "北境之外的國度",
   ARealmBeyondTheNorthernFrontierDesc: "我們的旗幟如今飄揚在波圖斯及雷蒂亞北部邊境之外。這個曾以阿爾卑斯山口為特徵的行省，如今在日耳曼尼亞擁有一處立足點；我們必須決定這個意外誕生的國度將走向何方。",
   PressOurClaimsInGermania: "在日耳曼尼亞推進我們的宣稱",
   SettleAndTaxOurConquests: "安置並徵稅我們的征服地",
   TrainAGovernmentForExpansion: "為擴張訓練政府",
   AnAlpineProtectorate: "阿爾卑斯保護國",
   AnAlpineProtectorateDesc: "雷蒂亞不斷壯大，而鄰近的諾里庫姆已淪為脆弱的殘餘。諾里庫姆使節尋求在我們權威下的庇護，以效忠換取保護，抵禦東部山口之外的對手。",
   ReceiveNoricumAsOurClient: "接納諾里庫姆為我們的附庸",
   RaetiaReachesTheMediterranean: "雷蒂亞通向地中海",
   RaetiaReachesTheMediterraneanDesc: "地中海沿岸的兩座港口如今聽命於我們的行政機構，讓不臨海的雷蒂亞首次擁有通往海洋的出口。當地商人、地方官與水手等待我們決定如何利用這片新海岸。",
   CollectTheHarborCustoms: "徵收港口關稅",
   CharterTheCoastalCities: "授予沿海城市特許狀",
   RecruitCrewsForOurFleet: "為我們的艦隊招募船員",
   RaetiaAscendant: "崛起的雷蒂亞",
   RaetiaAscendantDesc: "如今已有二十個核心地塊承認我們的法律，雷蒂亞再也不能被視為狹窄的邊疆行省。我們的議會必須決定，如何將這個擴大的國度轉化為持久的權威。",
   ClaimAMandateToRule: "取得統治授權令",
   SeekHonorsFromTheSenate: "向元老院尋求榮譽",
   ExpandTheProvincialOffices: "擴充行省官署",
   AGermanicRaetia: "日耳曼化的雷蒂亞",
   AGermanicRaetiaDesc: "日耳曼社群如今佔我們人口的四分之一。他們的戰士、農民與習俗已與我們的行省不可分割；我們必須決定，雷蒂亞本身是否應當擁有日耳曼身份。",
   MakeGermanicOurLeadingCulture: "讓日耳曼文化成為我們的主流文化",
