   ARaetianTriumphInItaliaDesc: "如今已有十個義大利地塊牢牢歸屬於我們的國度。昔日軍隊透過阿爾卑斯山口向北行軍的道路，如今承載著我們的官員南下；義大利的城市正等待著雷蒂亞統治將呈現何種面貌。",
   RuleThroughTheItalianCities: "透過義大利城市統治",
