   MulticulturalArmyDesc$1$2: "我方核心地塊中每存在一種文化，軍力$1（最高$2）",
   InlandAmbition: "內陸雄心",
   InlandAmbitionDesc$1: "進攻無出海口的行省時，所需戰爭分數$1",
   TriumphalUnity: "凱旋凝聚",
   TriumphalUnityDesc$1$2: "作為主導進攻方或防守方贏得戰爭後，$2年內獲得$1穩定度",
   TheRoadsOfNoricum: "諾里庫姆的道路",
   TheRoadsOfNoricumDesc: "新立的里程碑標誌著一項帝國軍事道路修復計劃，這些道路連線著拉烏里亞庫姆、維魯努姆與阿爾卑斯山口。帝國測量員要求我們的行政機構決定如何提供勞力與資金。",
   FundTheWholeRoadProgram: "資助整個道路計劃",
