   TheCentonariiOfFlaviaSolva: "弗拉維婭·索爾瓦的絨毯工匠",
   TheCentonariiOfFlaviaSolvaDesc: "塞普蒂米烏斯·塞維魯與卡拉卡拉的敕令確認了弗拉維婭·索爾瓦在業絨毯工匠的特權，但將為逃避公共義務而加入的富人排除在外。我們的地方官必須在修訂行會名冊時落實這一區分。",
   UpholdTheWorkersPrivileges: "維護勞動者的特權",
