   RaidsOnTheNoricanFrontierDesc: "報告稱，阿勒曼尼戰團越過多瑙河上游防線，襲擾諾里庫姆。邊境聚落向我們請求增兵，而暴露在外的地主則敦促我們花錢求和。",
