   PayTheRaidersToWithdraw: "付錢讓襲擊者撤退",
   ValeriansNorthernMuster: "瓦勒裡安的北方集結",
   ValeriansNorthernMusterDesc: "加盧斯皇帝命令瓦勒裡安在雷蒂亞與諾里庫姆集結軍隊，對抗埃米利安。瓦勒裡安的幕僚要求我們提供補給、新兵，以及行省行政機構的全面配合。",
   ProvisionValeriansArmy: "為瓦勒裡安的軍隊提供補給",
   ReinforceLegioIIItalica: "增援第二義大利軍團",
   KeepOurRecruitsAtHome: "將我們的新兵留在本土",
   DiocletiansFrontierReforms: "戴克裡先的邊境改革",
   DiocletiansFrontierReformsDesc: "戴克裡先治下要求加強邊境防禦的新帝國命令已傳到諾里庫姆。我們的工程師提議加固要塞、增設縱深補給庫，並擴建無需等待遠方兵工廠便能裝備多瑙河駐軍的工坊。",
   RebuildTheFrontierForts: "重建邊境要塞",
   ExpandTheMilitaryWorkshops: "擴建軍事工坊",
   ConcentrateTheGarrisons: "集中駐軍",
   NoricanBishopsAtSerdica: "塞爾迪卡的諾里庫姆主教",
   NoricanBishopsAtSerdicaDesc: "來自諾里庫姆的主教加入了在塞爾迪卡召集的會議，這是有組織的行省主教團最早的可靠記錄。他們的旅程給了我們一個機會，來確定我們與不斷壯大的教會之間的關係。",
   FundTheNoricanDelegation: "資助諾里庫姆代表團",
   RecognizeTheProvincialSees: "承認行省主教教座",
   KeepChurchAffairsLocal: "讓教會事務留在地方",
   TheBurgusAtTheYbbs: "伊布斯河畔的堡塔",
   TheBurgusAtTheYbbsDesc: "一塊銘文記載了伊布斯河口新建的一座邊境塔樓，由來自拉烏里亞庫姆的輔助部隊修築。我們可以將這座孤立的堡塔變成更廣泛防禦計劃的支點。",
   RaiseAChainOfStoneBurgi: "建造一連串石制堡塔",
