   RequireLaborFromNearbyTowns: "向附近城鎮徵用勞力",
   AlaricWaitsInNoricum: "阿拉里克在諾里庫姆等待",
   AlaricWaitsInNoricumDesc: "阿拉里克與他的哥特人駐紮在諾里庫姆，要求帝國宮廷為一場廢棄的戰役支付四千磅黃金。在宮廷回應之前，這支軍隊從我們城鎮與道路旁的土地獲取補給。",
   SupplyTheGothicCamp: "為哥特營地提供補給",
   CloseTheRoadsAndPasses: "封鎖道路與山口",
   PetitionTheCourtToPay: "請求宮廷支付款項",
   TheEvacuationOfNoricum: "撤離諾里庫姆",
   TheEvacuationOfNoricumDesc: "奧多亞塞的軍隊摧毀魯吉王國後，他的兄弟奧努爾夫命令河畔諾里庫姆剩餘的羅馬居民撤往義大利。各個家庭帶著馬車與牲畜聚集到要塞，而塞維裡努斯的修士們則為遺骸的旅程做準備。",
   OrganizeTheMarchToItalia: "組織前往義大利的遷徙",
   HoldTheFortifiedTowns: "守住設防城鎮",
   NegotiateTermsWithOdoacer: "與奧多亞塞商議條件",
   ThreeRoadsToWar: "通往戰爭的三條道路",
   ThreeRoadsToWarDesc: "我們的徵召場已擠滿士兵，稅收也足以支援一場帝國戰役。三條道路如今展現在我們面前：西方的阿爾卑斯山口、南方的義大利，以及東方的多瑙河道路。我們的議會必須決定在向帝國宮廷請願時支援哪一場戰役。",
   PetitionForARaetianCampaign: "請求在雷蒂亞發動戰役",
   PetitionForAnItalianCampaign: "請求在義大利發動戰役",
   PetitionForAPannonianCampaign: "請求在潘諾尼亞發動戰役",
   TheSeawardGate: "通往海洋的門戶",
   TheSeawardGateDesc: "四個沿海地塊如今聽命於我們的行政機構。河流道路將我們的權威帶到了亞得里亞海，開闢了貿易與徵稅的新出口。我們必須決定，這片海岸首先應當充實國庫、繁榮城鎮，還是擴充套件行省官署。",
   OpenTheCoastalMarkets: "開放沿海市場",
   ExtendTheTaxOffices: "擴大稅務機構",
   TheAlpineBalance: "阿爾卑斯的均勢",
   TheAlpineBalanceDesc: "我們的核心地塊日益穩固，而雷蒂亞對阿爾卑斯邊境的掌控卻在衰退。其外交官仍在尋求和平，但山口與邊境城鎮已在我們的觸及範圍內。我們必須決定，是按我們的條件提供保護，還是請求帝國宮廷為西部邊境發動戰爭。",
   OfferRaetiaOurProtection: "向雷蒂亞提供我們的保護",
   PetitionForWarOverThePasses: "請求為山口開戰",
   OurRealmOfManyPeoplesDesc: "我們的法律如今連線著從義大利到潘諾尼亞與雷蒂亞的道路。眾多民族與信仰共同生活在一個比舊行省更遼闊的國度中。我們的議會必須決定，什麼原則才能維繫這個新共同體。",
   PetitionForAMandateToRule: "請求統治授權",
   TolerateTheGatheredFaiths: "包容各地信仰",
   TolerateTheGatheredCultures: "包容各地文化",
   TheDalmatianFrontier: "達爾馬提亞邊境",
   TheDalmatianFrontierDesc: "我們的旗幟如今控制著達爾馬提亞的三個核心地塊，為我們帶來南部邊境與一條沿亞得里亞海的新通道。我們必須決定，是鞏固邊境、慶祝勝利，還是讓我們的軍隊為另一場戰役做好準備。",
   SecureTheSouthernFrontier: "確保南部邊境安全",
   CelebrateOurAdriaticVictory: "慶祝我們在亞得里亞海的勝利",
   PrepareTheNextCampaign: "準備下一場戰役",
   BeyondTheDanube: "多瑙河之外",
   BeyondTheDanubeDesc: "三個日耳曼地塊如今聽命於我們的法律。多瑙河不再是邊界，而是一條通往河流、道路與異族組成之國的道路。我們必須選擇哪種力量能將我們的權威帶得更遠：行政、外交，還是武力。",
   BuildTheNewAdministration: "建立新的行政機構",
   SendEnvoysAcrossTheDanube: "派遣使者越過多瑙河",
   PutTheFrontierUnderArms: "讓邊境進入戰備狀態",
   $1IsNotOnTheMap: "<Province>$1</Province>不在地圖上",
   AquincumBecomesAColonia: "阿昆庫姆升格為殖民市",
   AquincumBecomesAColoniaDesc: "塞普蒂米烏斯·塞維魯治下，阿昆庫姆已升格為殖民市。市議會期待新的特權，而老兵、商人和鄰近社群紛紛敦促我們決定，誰將從這座城市更高的地位中受益。",
   FundTheNewColoniasWorks: "資助新殖民市的建設",
   ConfirmTheLocalCharters: "確認地方特許狀",
   SellTheMunicipalOffices: "出售市政官職",
   CaracallaOnTheDanube: "多瑙河畔的卡拉卡拉",
   CaracallaOnTheDanubeDesc: "卡拉卡拉在邊境之外征戰後抵達多瑙河視察。布里蓋提奧的軍團、沿河要塞與邊牆各城紛紛請求我們的行政機構修繕設施並授予特權，而帝國宮廷正注視著我們。",
   RepairTheBrigetioDefenses: "修繕布里蓋提奧的防禦工事",
   RecountTheFrontierHouseholds: "重新清查邊境戶籍",
   PetitionForVeteranSettlers: "請求安置老兵殖民者",
   IngenuusAtSirmium: "錫爾米烏姆的因格努烏斯",
   IngenuusAtSirmiumDesc: "關於這場危機的混亂記載認為，因格努烏斯大約在這一年於錫爾米烏姆被擁立，當時加里恩努斯遠在潘諾尼亞之外。他的軍官要求補給，忠君將領在行省之外集結，而我們的城鎮擔心另一支羅馬軍隊很快就會到來。",
   ProvisionTheSirmiumGarrison: "供應錫爾米烏姆駐軍",
