   RightOfPlunder: "掠奪權",
   Pillage: "掠奪",
   TimedActionPillageDesc$1$2$3$4: "將所選地塊升級的等級與該地塊的升級次數各降低 $1，返還按當前修正計算的恢復該升級所需花費的 $2。該地塊增加 $3 動盪，持續 $4 年。",
   EliminateAtLeast$1BarbarianPolities: "消滅至少 $1 個蠻族政權",
   EliminatedBarbarianPolities: "已消滅的蠻族政權",
   TheSpoilsOfVictory: "勝利的戰利品",
   TheSpoilsOfVictoryDesc: "我們已摧毀一個蠻族政權。如今，將領們敦促我們效仿敗敵的手段，為行省謀利。掠奪我們的非核心地塊或許能增強行政與軍事實力，但當地居民不會忘記這場浩劫。",
   SanctionPlunderForOurProvince: "准許我省進行掠奪",
   HearthsBeyondTheRhine: "萊茵河彼岸的爐火",
   HearthsBeyondTheRhineDesc: "在科洛尼亞對岸的萊茵河畔，迪維提亞堡周圍有足夠空間開闢新的家園與田地。我們有足夠人手在旗幟下派出定居者，但從豎起第一道柵欄到迎來豐收，仍需多年辛勤勞作。地主們則敦促我們先整頓防線後方的莊園，在立下新界碑前充實國庫。",
   RaiseNewHearthsAtDivitia: "在迪維提亞建立新家園",
   EstablishASettlementAt$1: "在 $1 建立定居點",
   PutOurOwnEstatesInOrder: "整頓我們自己的莊園",
   $1IsCurrentlyUnsettled: "$1 當前尚未定居",
   $1IsEligibleForSettlement: "$1 符合定居條件",
   $1BordersOneOfOurCoreTiles: "$1 與我們的一個核心地塊接壤",
   NewRootsAt$1: "在 $1 扎下新根",
   NewRootsAtTemacineDesc$1: "在 $1 開闢新田產，既需要可靠的水源，也需要勤勞的人手。我們有足夠人口在此建立家園，但挖掘水井、開墾田地並建立可靠生計，仍需多年耐心耕耘。我們可以在內陸邊疆建立這處定居點，也可改善現有莊園的管理，以更快獲得回報。",
   EstablishHomesAt$1: "在 $1 建立家園",
   NorthernHearthsAt$1: "$1 的北境爐火",
   NorthernHearthsAtBremeniumDesc$1: "在 $1，我們可為北境帶來的不只是一支警戒森嚴的守軍。新的家庭可在軍用道路旁耕田放牧，將暴露在外的前哨轉變為長久的聚落。我們人手充足，但嚴酷季節與多年準備橫亙在第一縷爐火與繁榮之間。地主們則更希望改善那些已在創造收入的莊園。",
   RaiseNewHearthsAt$1: "在 $1 建立新家園",
   InlandHearthsAt$1: "$1 的內陸爐火",
   InlandHearthsAtFasDesc$1: "在北方沿海城鎮之外，$1 為願意在內陸開創新生活的家庭提供了一片土地。我們可派遣攜帶牲畜與工具的家庭，在我們的治理下建立家園，但聚落需要多年才能繁榮。現有莊園同樣有待關注，其管事承諾，若先整頓內務，便可帶來更豐厚的收入。",
   NewHoldingsAt$1: "$1 的新田產",
   NewHoldingsAtStanacumDesc$1$2$3: "在 $1 開闢新農莊，可協助供養 $2 與 $3 周邊的多瑙河沿岸聚落。我們的人民能提供起步所需的人手、牲畜與生活用具，但要獲得穩定收成仍需多年。我們必須在邊疆扎下新根與進一步整頓既有莊園之間做出選擇。",
   EstablishFarmsAt$1: "在 $1 建立農莊",
   NewFieldsAt$1: "$1 的新田地",
   NewFieldsAtPartiskonDesc$1: "$1 的開闊鄉野為東部邊疆的新田地與牧群提供了空間。我們有足夠人口在此建立聚落，但建造房屋、劃定邊界並開墾具生產力的土地，並非一季之功。莊園主認為，改善我們已在管理的農場，能為國庫帶來更穩妥的回報。",
   HearthsAt$1: "$1 的爐火",
   HearthsAtIciniacumDesc$1$2$3: "多瑙河邊疆不只能設置崗哨。在 $1，我們可在 $2 和 $3 的聚落附近建立家園與田地。我們有足夠人手開始拓殖，但新田產需經多年經營才能自給自足。地主們則敦促我們改善已納入治理的莊園。",
   ProclaimImperialGrandeur: "宣揚帝國榮耀",
