   GrantLand: "授予土地",
   TimedActionGrantLandDesc$1$2: "將一個與附庸接壤、非首都且未處於戰爭爭奪中的核心地塊授予該附庸。我們的土地稅$1，持續 $2 年。",
   AdoptClientsCause: "採納附庸訴求",
   TimedActionAdoptClientCauseDesc: "取得附庸針對另一行省的宣戰理由，並保留其剩餘有效期。",
